//! VDI conformance against measured TOS behaviour.
//!
//! See `vdi_reference/harness.rs` for what these tests cover and what they
//! deliberately do not. The case module is generated by
//! `tosdump/host/mkrusttests`; do not edit it by hand.
//!
//! Both files live in the `vdi_reference/` subdirectory so cargo does not
//! pick them up as integration-test targets of their own.

#[path = "vdi_reference/harness.rs"]
mod harness;

#[path = "vdi_reference/cases_r2.rs"]
mod cases_r2;

#[path = "vdi_reference/cases_r3.rs"]
mod cases_r3;

#[path = "vdi_reference/cases_v_series.rs"]
mod cases_v_series;

#[path = "vdi_reference/cases_v20.rs"]
mod cases_v20;

#[path = "vdi_reference/cases_v21.rs"]
mod cases_v21;

#[path = "vdi_reference/cases_v22.rs"]
mod cases_v22;
